class TokenBucket {
  /**
   * @param {Object} options
   * @param {number} options.capacity - Maksimum jeton kapasitesi.
   * @param {number} options.refillPerSecond - Saniyedeki dolum miktarı.
   * @param {Function} [options.now=() => Date.now()] - Mevcut zamanı milisaniye olarak döndüren fonksiyon.
   */
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive finite number");
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError("refillPerSecond must be a non-negative finite number");
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFunc = now;

    this.lastRefillTime = this.nowFunc();
    this.tokens = capacity; // Kova dolu başlar
    this.maxObservedTime = this.lastRefillTime;
  }

  /**
   * İçsel olarak jetonları günceller.
   * @private
   */
  _refill() {
    const currentTime = this.nowFunc();

    // Saat geri giderse veya aynıysa işlem yapma
    if (currentTime <= this.maxObservedTime) {
      return;
    }

    const elapsedMs = currentTime - this.maxObservedTime;
    const refillAmount = (elapsedMs / 1000) * this.refillPerSecond;

    this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
    this.maxObservedTime = currentTime;
  }

  /**
   * n adet jeton almaya çalışır.
   * @param {number} n 
   * @returns {boolean}
   */
  tryTake(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError("n must be a positive finite number");
    }

    this._refill();

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  /**
   * Mevcut jeton miktarını döndürür.
   * @returns {number}
   */
  available() {
    this._refill();
    return this.tokens;
  }

  /**
   * n jetonun kullanılabilir olması için gereken milisaniye.
   * @param {number} n 
   * @returns {number}
   */
  msUntil(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError("n must be a positive finite number");
    }

    // Kapasite n'den küçükse asla dolmaz (n > capacity durumu)
    if (n > this.capacity) {
      return Infinity;
    }

    // Dolum hızı 0 ise ve jetonlar yetmiyorsa
    if (this.refillPerSecond === 0 && this.available() < n) {
      return Infinity;
    }

    const currentTokens = this.available();
    if (currentTokens >= n) {
      return 0;
    }

    // Eksik jeton miktarını hesapla
    const needed = n - currentTokens;
    // Saniyede refillPerSecond geliyorsa, milisaniyede (refillPerSecond / 1000) gelir.
    // Süre = ihtiyaç / (hız / 1000) = (ihtiyaç * 1000) / hız
    const msRequired = (needed * 1000) / this.refillPerSecond;

    return Math.ceil(msRequired);
  }
}

module.exports = { TokenBucket };

