const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function test() {
    console.log("Running tests...");

    // 1. Temel Fonksiyonellik Testi
    let currentTime = 1000;
    const now = () => currentTime;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

    // Başlangıçta dolu olmalı
    assert.strictEqual(bucket.available(), 10, "Başlangıçta kova dolu olmalı");

    // Jeton alımı
    assert.strictEqual(bucket.tryTake(5), true, "5 jeton alınabilmeli");
    assert.strictEqual(bucket.available(), 5, "5 jeton alındıktan sonra 5 kalmalı");
    assert.strictEqual(bucket.tryTake(6), false, "Yetersiz jetonla tryTake false dönmeli");
    assert.strictEqual(bucket.available(), 5, "Yetersiz deneme sonrası jeton azalmamalı");

    // Zaman geçince dolum
    currentTime += 1000; // 1 saniye geçti -> 2 jeton gelmeli (toplam 5 + 2 = 7)
    assert.strictEqual(bucket.available(), 7, "1 saniye sonra 2 jeton eklenmeli");

    // Kapasite sınırı
    currentTime += 10000; // 10 saniye geçti -> 20 jeton gelmeli ama max 10 olmalı
    assert.strictEqual(bucket.available(), 10, "Kapasite aşılmamalı");

    // Saat geri giderse (maxObservedTime kontrolü)
    currentTime -= 5000; // 5 saniye geri gittik
    assert.strictEqual(bucket.available(), 10, "Saat geri giderse jeton artmamalı");
    currentTime += 100; // Saati tekrar ileri aldık (sadece çok az ilerledi)
    assert.strictEqual(bucket.available(), 10, "Saat geri gittikten sonra hemen dolum olmamalı");

    // 2. msUntil Testleri
    const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 5, now });
    // Şu an 10 jeton var. 5 jeton alalım -> 5 kaldı.
    bucket2.tryTake(5); 
    // 8 jetona ulaşmak için 3 jeton lazım. 
    // Saniyede 5 geliyorsa, 3 jeton için 3/5 = 0.6 saniye = 600ms gerekir.
    assert.strictEqual(bucket2.msUntil(8), 600, "msUntil doğru hesaplamalı (600ms)");

    // Mevcut jeton yeterliyse 0
    assert.strictEqual(bucket2.msUntil(4), 0, "Yeterli jeton varsa msUntil 0 olmalı");

    // Infinity durumları
    assert.strictEqual(bucket2.msUntil(11), Infinity, "n > capacity ise Infinity olmalı");

    const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now });
    bucket3.tryTake(5); // 5 kaldı
    assert.strictEqual(bucket3.msUntil(6), Infinity, "refill 0 ve yetersizse Infinity olmalı");

    // 3. Hata Kontrolleri (RangeError)
    try {
        new TokenBucket({ capacity: -1, refillPerSecond: 1 });
        assert.fail("Negatif capacity hata fırlatmalı");
    } catch (e) { assert.ok(e instanceof RangeError); }

    try {
        new TokenBucket({ capacity: 10, refillPerSecond: -1 });
        assert.fail("Negatif refill hata fırlatmalı");
    } catch (e) { assert.ok(e instanceof RangeError); }

    try {
        bucket2.tryTake(-1);
        assert.fail("Negatif n hata fırlatmalı");
    } catch (e) { assert.ok(e instanceof RangeError); }

    try {
        bucket2.msUntil("a");
        assert.fail("Geçersiz n tipi hata fırlatmalı");
    } catch (e) { assert.ok(e instanceof RangeError); }

    console.log("All tests passed!");
}

test();

